t.script:
function goBack() {
    var customRecordsUrl = '/customer/records';
    if (document.referrer.indexOf(customRecordsUrl) !== -1) {
        window.location.href = customRecordsUrl;
    } else if (document.referrer) {
        window.location.href = document.referrer;
    } else {
        window.location.href = customRecordsUrl;
    }
}
